'use strict';
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let S=null,tab='studio',project='default',kind='image',filter='all',mapping='shared',libraryKind='all',workflow=null,selected=new Set(),drafts={},rawFile=null,refIds=new Set(),lastPlan=null,pending=new Set();
const names={studio:'Studio',library:'Thư viện',srt:'SRT Video',film:'Làm phim',storyboard:'Ảnh tham chiếu',aff:'Video Aff',accounts:'Tài khoản',proxy:'Proxy',codex:'Codex AI',settings:'Cài đặt',guide:'Hướng dẫn kết nối'};
const icons={studio:'m12 3 2 6 6 2-6 2-2 6-2-6-6-2 6-2z',library:'M4 5h16v14H4z M7 14l3-3 3 3 3-4 4 5 M8 8h1',srt:'M3 5h18v14H3z M6 10h12 M6 14h8',film:'M3 8h18v12H3z M3 8l2-5h16l-2 5 M8 3l-2 5 M14 3l-2 5',storyboard:'M4 3h16v18H4z M7 16l3-4 3 3 3-6 4 7 M8 7h1',aff:'M5 7h14l1 14H4z M9 7V5a3 3 0 0 1 6 0v2',accounts:'M16 21v-3a4 4 0 0 0-8 0v3 M12 3a4 4 0 1 0 0 8a4 4 0 1 0 0-8 M20 21v-3a5 5 0 0 0-2-4',proxy:'M12 2a10 10 0 1 0 0 20a10 10 0 1 0 0-20 M2 12h20 M12 2c-5 5-5 15 0 20 M12 2c5 5 5 15 0 20',codex:'M8 5l-7 7 7 7 M16 5l7 7-7 7',settings:'M12 3v3 M12 18v3 M3 12h3 M18 12h3 M5 5l2 2 M17 17l2 2 M5 19l2-2 M17 7l2-2 M12 8a4 4 0 1 0 0 8a4 4 0 1 0 0-8'};
Object.assign(icons,{plus:'M12 5v14 M5 12h14',play:'M8 5l11 7-11 7z',upload:'M12 16V3 M7 8l5-5 5 5 M4 15v6h16v-6',list:'M8 6h13 M8 12h13 M8 18h13 M3 6h1 M3 12h1 M3 18h1',refresh:'M20 7a9 9 0 1 0 1 9 M20 2v6h-6',stop:'M5 5h14v14H5z',folder:'M3 7h7l2 2h9v12H3z M3 7V4h7l2 3',copy:'M9 8h12v13H9z M3 16V2h12v3',trash:'M3 6h18 M9 6V3h6v3 M6 6l1 15h10l1-15'});
const icon=k=>`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${icons[k]||(k==='guide'?icons.library:icons.studio)}"/></svg>`;
const buttonSymbols={'new-workflow':'plus','project-add':'plus','account-add':'plus','proxy-add':'plus','workflow-auto':'play','story-run':'play','create-run':'play','queue-start':'play','create-only':'plus','workflow-save':'plus','workflow-bulk':'list','workflow-queue':'list','story-character-add':'plus','story-batch':'storyboard','story-originals':'upload','story-image':'upload','story-import':'upload','import-prompts':'upload','import-srt':'upload','upload-refs':'upload','import-media':'upload','product-images':'upload','product-open':'proxy','product-helper':'aff','story-prompts':'copy','story-match':'studio','retry':'refresh','refresh':'refresh','queue-stop':'stop','open-output':'folder','tasks-delete':'trash','project-delete':'trash'};
const btn=(text,action,cls='',data='')=>{const symbol=buttonSymbols[action];let title=text;if(symbol)title=String(title).replace(/^[+＋▶↑▢☷▤⌫↻■♧▧↗⇧✧▱]\s*/,'');return `<button class="${cls}" data-action="${action}" ${data}>${symbol?icon(symbol):''}${title}</button>`};

const input=(label,name,value='',type='text',extra='')=>`<div class="field"><label>${label}</label><input type="${type}" name="${name}" value="${esc(value)}" ${extra}></div>`;
const area=(label,name,value='',extra='')=>`<div class="field"><label>${label}</label><textarea name="${name}" ${extra}>${esc(value)}</textarea></div>`;
const select=(label,name,options,value)=>{if(value!==undefined&&value!==null&&value!==''&&!options.some(o=>String(Array.isArray(o)?o[0]:o)===String(value)))options=[[value,String(value)+' (đã lưu)'],...options];return `<div class="field"><label>${label}</label><select name="${name}">${options.map(o=>{let [v,t]=Array.isArray(o)?o:[o,o];return `<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(t)}</option>`}).join('')}</select></div>`};
const check=(label,name,on=true)=>`<label><input type="checkbox" name="${name}" ${on?'checked':''}>${label}</label>`;
const languages=[['vi','Tiếng Việt'],['en','English (Tiếng Anh Quốc tế)'],['en-US','English - US (Tiếng Anh Mỹ)'],['en-GB','English - UK (Tiếng Anh Anh Quốc)'],['en-AU','English - Australia (Tiếng Anh Úc)'],['en-CA','English - Canada (Tiếng Anh Canada)'],['fr-CA','Français - Canada (Tiếng Pháp Canada)'],['ja','日本語 (Tiếng Nhật)'],['ko','한국어 (Tiếng Hàn)'],['es','Español (Tiếng Tây Ban Nha)'],['de','Deutsch (Tiếng Đức)'],['fr','Français (Tiếng Pháp)'],['it','Italiano (Tiếng Ý)'],['nl','Nederlands (Tiếng Hà Lan)'],['sv','Svenska (Tiếng Thụy Điển)'],['no','Norsk (Tiếng Na Uy)'],['da','Dansk (Tiếng Đan Mạch)'],['fi','Suomi (Tiếng Phần Lan)'],['de-CH','Deutsch - Schweiz (Thụy Sĩ)'],['en-SG','English - Singapore (Singapore)']];
const badge=(status)=>`<span class="badge ${esc(status)}">${({preparing:'Chuẩn bị',rendering:'Đang tạo',verifying:'Kiểm tra',download_error:'Lỗi tải',paused:'Tạm dừng',editing:'Đang dựng',planning:'Đang lập kịch bản',queued:'Chờ',running:'Đang chạy',submitting:'Đang gửi',downloading:'Đang tải',done:'Xong',error:'Lỗi',review:'Cần kiểm tra',draft:'Bản nháp',new:'Chưa đăng nhập',login:'Đang đăng nhập',ready:'Sẵn sàng',unverified:'Chưa xác minh',alive:'Hoạt động',unchecked:'Chưa kiểm tra'})[status]||esc(status)}</span>`;
function toast(text,error=false){$('#toast').textContent=text;$('#toast').className=error?'error':'';$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',error?11000:6500)}
async function api(path,data){let r=await fetch(path,data===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)}),v=await r.json();if(!r.ok)throw Error(v.error||'Thao tác thất bại');return v}
async function refresh(render=true){S=await api('/api/state');$('.version').textContent='v'+S.version;$('#running').textContent=S.running;const lic=S.license||{};if($('#license-info'))$('#license-info').innerHTML=licenseDetails(lic);$('#license-state').textContent=lic.active?'Còn '+lic.days_remaining+' ngày':({expired:'Đã hết hạn',revoked:'Đã thu hồi',unconfigured:'Chưa cấu hình bản quyền'})[lic.status]||'Chưa kích hoạt';$('#account-count').textContent=S.accounts.length?`${S.accounts.length} tài khoản · ${S.accounts.filter(a=>a.status==='ready'&&a.enabled!==false&&!a.held).length} sẵn sàng`:'Chưa có tài khoản';$('#status').innerHTML=`<i></i>${S.enabled?'Hàng đợi đang chạy':'Hàng đợi đang dừng'} · ${lic.required?'Phiên bản':'Bản phát triển'} ${S.version}`;applyTheme(S.settings.theme||'dark');if(render)draw();else if($('#announcement-banner'))$('#announcement-banner').outerHTML=announcementBanner()}
function remember(){const form=$('#view-form');if(form)drafts[tab]=['film','aff','storyboard'].includes(tab)?workflowData(tab):formData();if(tab==='studio'&&$('#prompts'))drafts.studio={raw:$('#prompts').value,delimiter:$('#delimiter').value}}

function empty(title,desc='',ic='◇'){return `<div class="empty"><div class="empty-icon">${ic}</div><strong>${title}</strong><small>${desc}</small></div>`}
function pagebar(title,desc='',actions=''){return `<div class="pagebar"><h1>${title}</h1><span class="muted">${desc}</span>${actions}</div>`}
function projectOptions(value=project){return S.projects.map(p=>`<option value="${p.id}" ${p.id===value?'selected':''}>${esc(p.name)} (${S.tasks.filter(t=>t.project===p.id).length})</option>`).join('')}
function side(module,title,desc){let rows=S.workflows.filter(w=>w.module===module);return `<aside class="sidebar">${btn('+ '+title,'new-workflow','active',`data-module="${module}"`)}${btn('☷ Hàng chờ','workflow-queue','',`data-module="${module}"`)}<small style="padding:10px">DỰ ÁN · ${rows.length}</small>${rows.map(w=>`<button data-action="open-workflow" data-id="${w.id}">${esc(w.name)}<small>${badge(w.status)}</small></button>`).join('')}</aside>`}
function draw(){if(!S)return;$('#nav').innerHTML=Object.entries(names).map(([k,v])=>`<button data-action="tab" data-tab="${k}" class="${tab===k?'active':''}">${icon(k)}${v}</button>`).join('');$('#main').innerHTML=({studio:studio,library:library,srt:srt,film:film,storyboard:storyboard,aff:aff,accounts:accounts,proxy:proxy,codex:codex,settings:settings,guide:connectionGuide}[tab])();}
function studio(){let tasks=S.tasks.filter(t=>t.project===project),shown=tasks.filter(t=>filter==='all'||(filter==='running'?['running','preparing','submitting','rendering','verifying','downloading'].includes(t.status):filter==='error'?['error','review','download_error'].includes(t.status):filter==='queued'?['queued','paused'].includes(t.status):t.status===filter)),d=drafts.studio||{};return `${announcementBanner()}<div class="projectbar"><select id="project">${projectOptions()}</select>${btn('+','project-add')}${btn('✎','project-rename')}${btn('⌫','project-delete','danger')}<span class="muted" style="margin-left:12px">${tasks.filter(t=>t.status==='done').length}/${tasks.length} xong</span><div class="progress" style="width:100px"><div style="width:${tasks.length?tasks.filter(t=>t.status==='done').length/tasks.length*100:0}%"></div></div><div class="right"><span class="muted">Trình duyệt</span>${btn(S.settings.window==='offscreen'?'Chạy ẩn':'Hiện cửa sổ','browser-mode','outline')}${btn('Hiện trình duyệt','show-browser','outline')}${btn('▱ Thư mục kết quả','open-output','outline')}</div></div><div class="studio-layout"><section class="panel taskpanel"><div class="task-toolbar"><div class="filterbar">${[['all','Tất cả'],['queued','Chờ'],['running','Đang chạy'],['done','Xong'],['error','Lỗi']].map(([k,n])=>btn(`${n}<span class="count">${k==='all'?tasks.length:tasks.filter(t=>k==='running'?['running','preparing','submitting','rendering','verifying','downloading'].includes(t.status):k==='error'?['error','review','download_error'].includes(t.status):k==='queued'?['queued','paused'].includes(t.status):t.status===k).length}</span>`,'task-filter','pill '+(filter===k?'active':''),`data-value="${k}"`)).join('')}</div><div class="task-actions"><label><input type="checkbox" id="select-all">Tất cả</label><select id="quick-select" style="width:105px;padding:5px;font-size:11px"><option value="">Chọn nhanh</option><option value="error">Tác vụ lỗi</option><option value="done">Đã xong</option><option value="queued">Đang chờ</option><option value="image">Chỉ ảnh</option><option value="video">Chỉ video</option></select>${btn('▤ Ghép video','merge-tasks')}${btn('▶ Chạy','queue-start','primary')}${btn('↻ Chạy lại lỗi','retry')}${btn('■ Dừng','queue-stop','danger')}${btn('⌫ Xóa','tasks-delete','danger')}<input id="task-search" placeholder="Tìm prompt…"></div></div><table><thead><tr><th></th><th>STT</th><th>TÊN & PROMPT</th><th>LOẠI</th><th>TÀI KHOẢN</th><th>TRẠNG THÁI</th><th>THAO TÁC</th></tr></thead><tbody>${shown.map((t,i)=>`<tr data-task-row data-search="${esc((t.prompt+' '+t.id).toLowerCase())}"><td><input type="checkbox" data-task="${t.id}" ${selected.has(t.id)?'checked':''}></td><td>${t.sequence||i+1}</td><td class="prompt" title="${esc(t.prompt)}">${esc(t.prompt.slice(0,150))}${t.error?`<div class="status-note" style="color:var(--red)">${esc(t.error)}</div>`:''}</td><td>${t.kind==='image'?'Ảnh':t.kind==='image_video'?'Ảnh → Video':'Video'}</td><td>${esc(S.accounts.find(a=>a.id===t.account)?.name||'—')}</td><td>${badge(t.status)}<small>${t.outputs?.length||0}/${t.count} kết quả</small></td><td>${btn('Xem','task-detail','',`data-id="${t.id}"`)}</td></tr>`).join('')}</tbody></table>${!shown.length?empty('Chưa có tác vụ trong dự án này','Nhập prompt ở bảng bên phải rồi chọn Tạo & chạy hoặc Chỉ thêm.','✧'):''}</section><aside class="panel inputpanel"><div class="segmented">${[['video','Video'],['image','Ảnh'],['image_video','Ảnh → Video']].map(([k,n])=>btn(n,'kind',kind===k?'active':'',`data-value="${k}"`)).join('')}</div><label>Prompt <span class="muted" id="prompt-count"></span> <span style="float:right">${btn('↑ .txt','import-prompts')}${btn('×','clear-prompts')}</span></label><textarea id="prompts" placeholder="promt08&#10;Dán nguyên văn prompt của bạn ở đây…">${esc(d.raw||'')}</textarea><div class="field" style="margin-top:12px"><label>Ký tự ngăn cách</label><input id="delimiter" value="${esc(d.delimiter??'promt08')}" placeholder="Trống = một prompt nguyên khối"></div><label>Ảnh tham chiếu <span class="muted">${refIds.size}</span> ${kind==='image_video'?btn('Batch thư mục','upload-folder'):''}</label><div class="segmented">${[['pair','Ghép cặp'],['shared','Dùng chung'],['name','Theo tên']].map(([k,n])=>btn(n,'mapping',mapping===k?'active':'',`data-value="${k}"`)).join('')}</div><div class="ref-drop" data-action="upload-refs">＋ Kéo thả hoặc chọn ảnh từ máy<small style="display:block">PNG / JPG / WebP · Gắn đúng ảnh cho từng prompt</small></div><div class="ref-grid">${S.refs.filter(r=>r.kind==='image'&&(!r.project||r.project===project)).map(r=>`<div class="ref-tile"><img src="/refs/${r.id}" alt=""><label><input type="checkbox" data-ref="${r.id}" ${refIds.has(r.id)?'checked':''}></label><small title="${esc(r.name)}">${esc(r.code||r.name)}</small></div>`).join('')}</div><div class="grid two">${select('Tỷ lệ','task-ratio',['16:9','9:16','1:1','4:3','3:4'],d.ratio||'16:9')}${kind==='image'?select('Số ảnh / prompt','task-count',['1','2','3','4'],d.count||'1'):'<input type="hidden" name="task-count" value="1">'}</div><div class="actions">${btn('▶ Tạo & chạy','create-run','primary')}${btn('＋ Chỉ thêm','create-only','outline')}</div><div class="status-note">Prompt gốc được giữ nguyên. Tham chiếu và cài đặt được lưu riêng.</div></aside></div>`}
function library(){let rows=S.media.filter(m=>libraryKind==='all'||m.kind===libraryKind);return pagebar('Thư viện','',`<div class="filterbar">${[['all','Tất cả'],['video','Video'],['image','Ảnh']].map(([k,n])=>btn(n+` <span class="count">${S.media.filter(m=>k==='all'||m.kind===k).length}</span>`,'library-filter','pill '+(libraryKind===k?'active':''),`data-value="${k}"`)).join('')}</div><div class="right"><select id="library-project" style="width:180px"><option value="">Tất cả dự án</option>${projectOptions('')}</select><input id="library-search" placeholder="Tìm tên, prompt…" style="width:220px">${btn('↑ Nhập file','import-media','outline')}${btn('↻ Làm mới','refresh')}</div>`)+(rows.length?`<div class="library">${rows.map(m=>`<article class="media-card" data-media-card data-project="${m.project}" data-search="${esc((m.name+' '+m.prompt).toLowerCase())}"><div class="media-thumb" data-action="preview" data-id="${m.id}"><img src="/media/${m.id}/thumb" alt="${esc(m.name)}"><span class="badge">${m.kind==='video'?'▷ Video':'▧ Ảnh'}</span></div><div class="media-info"><strong title="${esc(m.name)}">${esc(m.name)}</strong><div class="excerpt">${esc(m.prompt)}</div><small>${esc(S.projects.find(p=>p.id===m.project)?.name||'Dự án')} · ${m.width}×${m.height}<br>${(m.size/1048576).toFixed(1)} MB · ${new Date(m.created*1000).toLocaleString('vi-VN')}</small><div class="actions">${btn('Mở file','open-media','',`data-id="${m.id}"`)}${btn('Thư mục','media-folder','',`data-id="${m.id}"`)}</div></div></article>`).join('')}</div>`:empty('Chưa có kết quả','Ảnh và video tạo xong sẽ xuất hiện ở đây.','▧'))}
function srt(){let list=S.workflows.filter(w=>w.module==='srt'),w=list.find(w=>w.id===workflow);return pagebar('SRT → Video · Phim','Ảnh / clip chạy khớp lời thoại SRT · nhân vật & bối cảnh đồng bộ theo mạch truyện',btn('↑ Nhập file SRT','import-srt','primary'))+`<div class="workspace"><aside class="sidebar">${list.length?list.map(p=>btn(esc(p.name)+`<small>${p.scenes.length} đoạn · ${badge(p.status)}</small>`,'open-workflow',p.id===workflow?'active':'',`data-id="${p.id}"`)).join(''):empty('Chưa có dự án SRT','','▤')}</aside><div class="content">${w?`<section class="panel"><h2>${esc(w.name)}</h2><div class="inline">${badge(w.status)}<span class="muted">${w.scenes.length} đoạn · ${w.scenes.at(-1).end.toFixed(2)} giây</span></div><div class="actions">${btn('↑ Nhập ảnh / clip','import-media','outline')}${btn('▤ Dựng video + SRT','render-srt','primary',`data-id="${w.id}"`)}</div><div class="notice">Chọn ảnh hoặc clip khớp nội dung cho từng đoạn. Clip được cắt/lặp theo thời lượng SRT; khoảng trống được giữ trên timeline.</div>${w.scenes.map((s,i)=>`<div class="scene srt-row"><b>${i+1}</b><small>${s.start.toFixed(3)} → ${s.end.toFixed(3)}<br>${s.duration}s</small><span style="white-space:pre-wrap">${esc(s.text)}</span><select data-srt-media="${i}"><option value="">Chọn ảnh / clip…</option>${S.media.map(m=>`<option value="${m.id}" ${s.media===m.id?'selected':''}>${esc(m.name)}</option>`).join('')}</select></div>`).join('')}</section>`:''}</div></div>`}
function voiceKeyEditor(id){let saved=!!S.voicetube?.has_key;return `<div class="voice-key-editor"><div class="voice-key-row"><input id="${id}" type="password" autocomplete="off" spellcheck="false" aria-label="API key VoiceTube" placeholder="${saved?'Key đã lưu · nhập key mới để thay':'Dán API key VoiceTube (fvc_…)'}">${btn('Lưu key','voice-key-save','outline',`data-input="${id}"`)}</div><small class="voice-key-help">Lấy key ở <a href="https://voicetube.net" target="_blank" rel="noopener noreferrer">voicetube.net</a> → API đối tác. Key được mã hóa, lưu trên máy này và dùng chung cho mọi phim.</small><small class="voice-key-state" data-voicetube-status role="status">${saved?'Đã lưu key trên máy · Chưa xác minh tạo giọng VoiceTube.':'Chưa lưu key · Chưa kết nối tạo giọng VoiceTube.'}</small></div>`}
function voiceControls(d){let voice=d.voice==='voicetube'?'voicetube':'muse';return `<div class="voice-control"><label>Giọng nhân vật</label><div class="voice-options" role="radiogroup" aria-label="Giọng nhân vật">${[['muse','Giọng gốc Muse'],['voicetube','Lồng tiếng VoiceTube']].map(([value,title])=>`<label class="voice-choice ${voice===value?'active':''}"><input type="radio" name="voice" value="${value}" ${voice===value?'checked':''}><span>${title}</span></label>`).join('')}</div><div data-voice-key-panel ${voice==='voicetube'?'':'hidden'}>${voiceKeyEditor('film-voicetube-key')}</div></div>`}

function commonFilm(d={}){return `${area('Ý tưởng phim <span class="muted">(nhân vật, bối cảnh, mâu thuẫn, cú twist, cái kết)</span>','idea',d.idea||'','placeholder="Nhập ý tưởng phim của bạn…" style="min-height:125px"')}<div class="grid four">${input('Tên phim <span class="muted">(trống = Muse đặt)</span>','name',d.name||'')}${select('Thể loại','genre',['Muse tự chọn theo ý tưởng','Tự viết thể loại…'],d.genre)}${input('Độ dài (phút)','duration',d.duration||2,'number','min="1" max="5"')}${select('Ngôn ngữ thoại','language',languages,d.language||'vi')}</div><div class="grid two">${input('Phong cách hình ảnh','style',d.style||'')}${input('Yêu cầu thêm về hình','visual_notes',d.visual_notes||'')}</div><div class="grid two">${select('Tỷ lệ khung hình','ratio',[['16:9','16:9 YouTube'],['9:16','9:16 Shorts'],['1:1','1:1']],d.ratio||'16:9')}${select('Nhạc nền','music',[['muse','Muse tạo'],['file','File của tôi'],['none','Không nhạc']],d.music||'none')}</div><div data-music-file-panel ${d.music==='file'?'':'hidden'}>${input('File nhạc của tôi (đường dẫn)','music_file',d.music_file||'')}</div>${voiceControls(d)}<div class="checks">${check('Có người dẫn chuyện','narration',!!d.narration)}${check('Chèn phụ đề','subtitles',d.subtitles!==false)}${check('Tự sửa cảnh bị từ chối & tạo lại','retry',!!d.retry)}</div>`}
function film(){let w=S.workflows.find(w=>w.id===workflow&&w.module==='film'),d=workflowDraft('film');return pagebar('Làm phim','Nhập ý tưởng → Muse viết kịch bản, vẽ nhân vật, quay từng cảnh → tool dựng thành phim',btn('＋ Phim mới','new-workflow','primary','data-module="film"'))+`<div class="workspace">${side('film','Phim mới')}<div class="content"><form id="view-form" class="panel formpanel"><h2>▣ &nbsp;Làm phim từ ý tưởng</h2><small>Nhập ý tưởng và chọn cài đặt. Quản lý kịch bản, nhân vật, ảnh cảnh, clip và dựng phim theo từng công đoạn.</small>${commonFilm(d)}<div class="notice">Kịch bản được lập theo thời lượng; mỗi shot có nhân vật, góc quay và lời thoại riêng. Các bước phụ thuộc Muse được xác nhận bằng file thực tế.</div><div class="actions">${btn('▶ Làm phim tự động','workflow-auto','primary','data-module="film"')}${btn('＋ Tạo dự án, chạy từng bước','workflow-save','outline','data-module="film"')}${btn('☷ Thêm nhiều phim vào hàng chờ…','workflow-bulk','','data-module="film"')}</div><ol class="steps"><li><strong>Kịch bản theo cảnh:</strong> mục tiêu, trở ngại, bước ngoặt và quan hệ nhân quả.</li><li><strong>Ngữ pháp shot:</strong> toàn cảnh, hai người, cận người nói và phản ứng.</li><li><strong>Đạo diễn soát kịch bản:</strong> tính hợp lý, xưng hô và mạch truyện.</li><li><strong>Diễn xuất và đạo cụ:</strong> mô tả cụ thể, tham chiếu nhất quán.</li><li><strong>Nhạc nền:</strong> Muse tạo, file riêng hoặc không nhạc.</li><li><strong>Ảnh nhân vật → ảnh cảnh:</strong> giữ khuôn mặt, tóc và trang phục.</li><li><strong>Clip thoại:</strong> tạo clip, kiểm tra lời nói trước khi duyệt.</li><li><strong>Dựng phim:</strong> ghép cảnh, phụ đề và âm thanh.</li></ol>${w?`<div class="notice">${badge(w.status)} ${esc(w.error||'Đã lưu dự án trên máy.')}</div>`:''}</form></div></div>`}
const sceneMoods=['Tự động theo mạch phim','Điện ảnh ngoài rạp','Hành động sống động','Cảm xúc sâu lắng','Kịch tính hồi hộp','Cao trào bùng nổ','Ấm áp trong trẻo','Bí ẩn cuốn hút'];
const sceneCounts=[4,6,8,10,12,15,20,24,30];
const regions=['Bắc - Hà Nội','Nam - Sài Gòn','Trung - Huế'];
const normalizeLines=s=>String(s??'').replace(/\r\n|\r/g,'\n');
const segment=(name,options,value,extra='')=>`<div class="choice-segments" ${extra}>${options.map(o=>{const [v,t]=Array.isArray(o)?o:[o,o];return `<label class="segment-choice"><input type="radio" name="${name}" value="${esc(v)}" ${String(v)===String(value)?'checked':''}><span>${esc(t)}</span></label>`}).join('')}</div>`;
function workflowDraft(module){const saved=S.workflows.find(w=>w.id===workflow&&w.module===module);return {...(saved||{}),...(drafts[module]||{})}}
function newCharacter(i=1){return {id:'CHAR_'+String(i).padStart(3,'0'),name:'Nhân vật '+i,appearance:'Giữ đồng nhất khuôn mặt, kiểu tóc, trang phục và thần thái theo ảnh tham chiếu xuyên suốt mọi phân cảnh.',voice:'Giọng rõ chữ, tốc độ vừa, âm sắc ổn định; giữ nguyên giọng trong mọi phân cảnh.',ref:''}}
function newScene(character){return {prompt:'',refs:[],duration:15,mood:sceneMoods[0],opening:'',ending:'',characters:character?[character]:[]}}
function storyModel(){const d=workflowDraft('storyboard');if(!Array.isArray(d.characters))d.characters=[newCharacter()];if(!Array.isArray(d.scenes))d.scenes=Array.from({length:10},()=>newScene(d.characters[0]?.id));d.original_refs??=[];return d}
function durationText(seconds){const n=Math.round(seconds);return `${Math.floor(n/60)} phút ${n%60} giây`}
function announcementBanner(){const a=S.announcement||{};return `<div id="announcement-banner" class="studio-hero owner-announcement" ${a.enabled===false?'hidden':''}><div><strong>${esc(a.title||'VANTRONG08 AI VIP PRO')}</strong><div class="tiny">${esc(a.body||'')}</div></div>${a.link&&/^https:\/\//.test(a.link)?`<a class="banner-link" href="${esc(a.link)}" target="_blank" rel="noopener noreferrer">${esc(a.button||'Xem chi tiết')} ↗</a>`:'<span class="hero-tag">STUDIO · IMAGE & VIDEO</span>'}</div>`}
function applyTheme(value){document.body.classList.toggle('light',value==='light');document.querySelectorAll('[data-theme-value]').forEach(b=>{b.classList.toggle('active',b.dataset.themeValue===value);b.setAttribute('aria-pressed',String(b.dataset.themeValue===value))});try{localStorage.setItem('vt08-theme',value)}catch{}}
function collectCharacters(){return [...document.querySelectorAll('[data-character-card]')].map(card=>({id:card.dataset.characterCard,name:card.querySelector('[data-character-name]').value,appearance:card.querySelector('[data-character-appearance]').value,voice:card.querySelector('[data-character-voice]').value,ref:card.querySelector('[data-character-ref]').value}))}
function collectScenes(base){return [...document.querySelectorAll('[data-scene]')].map((el,i)=>{const old=base.scenes?.[i]||{},text=el.querySelector('[data-scene-prompt]').value;return {...old,prompt:text===normalizeLines(old.prompt)?old.prompt:text,refs:el.dataset.refId?[el.dataset.refId]:[],storyboard_name:el.querySelector('[data-storyboard-name]').value,mood:el.querySelector('[data-scene-mood]').value,opening:el.querySelector('[data-scene-opening]').value,ending:el.querySelector('[data-scene-ending]').value,duration:Number(el.querySelector('[data-scene-duration]').value),characters:[...el.querySelectorAll('[data-scene-character]:checked')].map(c=>c.value)}})}
function storyScene(s,i,n,characters){const label=String(i+1).padStart(2,'0'),rid=s.refs?.[0],r=S.refs.find(r=>r.id===rid),chosen=Array.isArray(s.characters)?s.characters:characters.filter(c=>String(s.characters||'').includes(c.id)).map(c=>c.id);return `<article class="story-scene" data-scene="${i}" data-ref-id="${esc(rid||'')}"><div class="story-left"><div class="scene-title"><b>Ảnh Storyboard Cảnh ${label}</b><span class="badge">${rid?'Đã chọn':'Chưa chọn'}</span></div><button type="button" class="story-image-drop" data-action="story-image" data-index="${i}" data-drop-kind="scene" data-index-drop="${i}" aria-label="Chọn ảnh Storyboard cảnh ${i+1}">${rid?`<img src="/refs/${rid}" alt="${esc(r?.name||'Ảnh cảnh '+label)}">`:`<span class="upload-symbol">▧</span><strong>Chọn / Kéo ảnh Storyboard Cảnh ${label}</strong><small>Ảnh tham chiếu bên trái</small>`}</button><input data-storyboard-name value="${esc(s.storyboard_name||'Storyboard cảnh '+label)}" aria-label="Tên ảnh cảnh ${i+1}"><div class="actions compact">${btn('↑ Đổi ảnh cảnh '+label,'story-image','',`data-index="${i}"`)}${rid?btn('Bỏ ảnh','story-remove-image','',`data-index="${i}"`):''}</div><div class="continuity-tag">↗ ${i===0?'Mở đầu phim (Cảnh 01)':`Nối từ Cảnh ${String(i).padStart(2,'0')}`} → ${i===n-1?'Kết thúc phim':`Cảnh cuối khớp sang Mở đầu Cảnh ${String(i+2).padStart(2,'0')}`}</div></div><div class="story-right"><div class="scene-heading"><b>Phân cảnh ${label} / ${n}</b><small>Prompt câu lệnh theo ảnh Storyboard bên trái</small></div><label class="scene-duration-label"><input data-scene-duration type="number" min="1" max="300" value="${s.duration||15}" aria-label="Thời lượng dự kiến cảnh ${i+1}"> giây dự kiến</label><div class="scene-mood"><label>Nhạc & Cảm xúc cảnh:</label><select data-scene-mood aria-label="Nhạc và cảm xúc cảnh ${i+1}">${sceneMoods.map(x=>`<option ${x===(s.mood||sceneMoods[0])?'selected':''}>${esc(x)}</option>`).join('')}</select></div><textarea data-scene-prompt aria-label="Prompt cảnh ${i+1}" placeholder="Nhập câu lệnh phân cảnh ${label} khớp với ảnh Storyboard bên trái: Hành động diễn ra thế nào, góc máy quay, âm thanh hành động và nhân vật nào nói câu thoại gì?">${esc(s.prompt||'')}</textarea><div class="grid two frame-fields"><div><label>Khung mở đầu Cảnh ${label} (theo Storyboard)</label><input data-scene-opening value="${esc(s.opening??s.continuity??'')}" placeholder="${i===0?'Mở đầu bộ phim từ khung hình này':'Nối tiếp khung kết thúc cảnh trước'}"></div><div><label>Cảnh cuối Cảnh ${label}${i<n-1?' (= Mở đầu Cảnh '+String(i+2).padStart(2,'0')+')':''}</label><input data-scene-ending value="${esc(s.ending||'')}" placeholder="Kết cảnh dẫn mượt sang cảnh tiếp"></div></div><div class="scene-characters"><small>Nhân vật & Giọng cố định trong cảnh ${label}:</small>${characters.map(c=>`<label><input type="checkbox" data-scene-character value="${esc(c.id)}" ${chosen.includes(c.id)?'checked':''}>${esc(c.name||c.id)}</label>`).join('')||'<small>Chưa có nhân vật.</small>'}</div></div></article>`}
function storyboard(){const d=storyModel(),scenes=d.scenes,chars=d.characters,ready=S.accounts.filter(a=>a.status==='ready'&&a.enabled!==false&&!a.held).length,limit=Number(d.concurrency_limit||10);return pagebar('Video từ ảnh tham chiếu','Dàn 4–30 phân cảnh · Trái: ảnh Storyboard · Phải: prompt · Khớp cảnh 1 → N')+`<div class="workspace">${side('storyboard','Dàn phân cảnh mới')}<div class="content"><form id="view-form" class="story-form"><section class="panel story-intro"><h2>Làm Phim Bằng Ảnh Tham Chiếu Storyboard (4–30 Phân Cảnh)</h2><p>Dàn hàng ngang trực quan: <b>Bên trái là ảnh tham chiếu Storyboard của từng phân cảnh — Bên phải là Prompt câu lệnh phân cảnh đó.</b> Cài đặt mạch nối, nhân vật, giọng nói và hậu kỳ cho toàn bộ phim.</p><div class="workflow-pills"><span>1 &nbsp; Chọn 4–30 phân cảnh</span><span>2 &nbsp; Trái: Ảnh Storyboard · Phải: Prompt</span><span>3 &nbsp; Khớp Cảnh 1 → Cảnh N</span><span>4 &nbsp; Nối phim, Nhạc & Phụ đề</span></div></section><section class="panel character-section"><div class="section-heading"><h3>♙ &nbsp; Đồng nhất nhân vật, giọng nói & Ảnh gốc tham chiếu</h3>${btn('＋ Thêm nhân vật','story-character-add')}</div><div class="checks">${check('Đồng nhất ngoại hình nhân vật trong mọi phân cảnh','same_character',d.same_character!==false)}${check('Đồng nhất giọng nói cố định trong mọi phân cảnh','same_voice',d.same_voice!==false)}${check('Khóa mạch nối: Cảnh cuối phân cảnh trước = Mở đầu phân cảnh sau (1 → N)','continuity',d.continuity!==false)}${check('Chuẩn bị hậu kỳ rạp: nối mượt, nhạc nền theo cảnh & phụ đề đa ngôn ngữ','postproduction',d.postproduction!==false)}</div><div class="original-upload" data-drop-kind="original"><div class="upload-symbol">⇧</div><div><strong>Tải ảnh gốc nhân vật / bối cảnh chung (1–4 ảnh) hoặc tải ảnh Storyboard riêng ở từng phân cảnh bên dưới</strong><small>PNG, JPG, WebP · tối đa 20 MB/ảnh · Giữ nguyên khuôn mặt, trang phục và phong cách xuyên suốt bộ phim</small></div>${btn('Chọn ảnh gốc','story-originals','outline')}</div><div class="reference-strip" data-original-refs>${d.original_refs.map(id=>`<div data-ref-id="${id}"><img src="/refs/${id}" alt="Ảnh gốc tham chiếu">${btn('×','story-original-remove','',`data-id="${id}" aria-label="Bỏ ảnh gốc"`)}</div>`).join('')}</div><p class="muted">Mỗi nhân vật có hồ sơ ngoại hình và giọng nói cố định xuyên suốt từ phân cảnh 1 đến phân cảnh thứ N.</p>${chars.map(c=>`<div class="character-card" data-character-card="${esc(c.id)}"><button type="button" class="character-remove" data-action="story-character-remove" data-id="${esc(c.id)}" aria-label="Xóa nhân vật">×</button><div class="grid two"><div><label>Tên nhân vật</label><input data-character-name value="${esc(c.name)}"></div><div><label>Ngoại hình cố định xuyên suốt</label><textarea data-character-appearance>${esc(c.appearance||'')}</textarea></div><div><label>Giọng nói đồng nhất xuyên suốt</label><textarea data-character-voice>${esc(c.voice||'')}</textarea></div><div><label>Ảnh nhân vật</label><select data-character-ref><option value="">Theo mô tả / Storyboard</option>${S.refs.filter(r=>r.kind==='image').map(r=>`<option value="${r.id}" ${c.ref===r.id?'selected':''}>${esc(r.name)}</option>`).join('')}</select><small>Mã riêng: ${esc(c.id)}</small></div></div></div>`).join('')}</section><section class="panel"><h3>☷ &nbsp; Cài đặt bộ phim & Ngôn ngữ</h3><div class="grid two">${input('Tên bộ phim / dự án phân cảnh','name',d.name||'','text','placeholder="Ví dụ: Hành Trình Dưới Ánh Hoàng Hôn"')}${select('Tỷ lệ khung hình','ratio',[['16:9','16:9 · Phim Rạp / YouTube'],['9:16','9:16 · Shorts / Reels / TikTok'],['1:1','1:1 · Vuông']],d.ratio||'16:9')}</div><div class="grid three">${select('Ngôn ngữ thoại chính','language',languages,d.language||'vi')}${select('Giọng vùng (Tiếng Việt)','region',regions,d.region||regions[0])}${select('Số lượng chạy đồng thời','concurrency_limit',[4,6,8,10,15,20,25,30].map(n=>[String(n),n+' tác vụ đồng thời']),String(limit))}</div><small>Yêu cầu: <span data-requested-limit>${limit}</span> · Hiện có thể chạy tối đa: ${Math.min(ready,S.settings.account_limit,S.settings.thread_limit,limit)} · Tài khoản sẵn sàng: ${ready} · Luồng hiện tại: ${S.settings.thread_limit}</small></section><section class="panel story-scenes-panel"><h3>☷ &nbsp; Dàn Hàng Ngang Storyboard & Prompt Từng Phân Cảnh (${scenes.length} phân cảnh · Chọn từ 4 đến 30)</h3><small>Bên trái: Ảnh tham chiếu Storyboard · Bên phải: Câu lệnh phân cảnh & Khớp nối cảnh 1 → N</small><div class="scene-count-tools"><label>Chọn số phân cảnh (4–30)</label><select id="scene-preset">${Array.from({length:27},(_,i)=>i+4).map(n=>`<option value="${n}" ${n===scenes.length?'selected':''}>${n} phân cảnh</option>`).join('')}</select><label>Hoặc nhập số</label><input id="scene-count" type="number" min="4" max="30" value="${scenes.length}">${btn('Áp dụng','scene-apply')}</div><div class="actions scene-bulk-tools">${btn('▧ Chọn loạt ảnh Storyboard (Cảnh 1 → '+scenes.length+')','story-batch','primary')}${btn('✧ Tự khớp mạch nối Cảnh 1 → '+scenes.length,'story-match')}${btn('▢ Dán nhiều câu lệnh','story-prompts')}${btn('↑ Nhập .txt','story-import')}</div><div class="scene-quick"><small>Chọn nhanh:</small>${sceneCounts.map(n=>btn(n+' cảnh','scene-quick',n===scenes.length?'active':'',`data-value="${n}"`)).join('')}</div><p class="muted">Mỗi hàng gồm: Cột Trái là ảnh Storyboard tham chiếu của đúng phân cảnh đó; Cột Phải là Prompt câu lệnh, thoại và khóa nối cảnh.</p><div id="scene-list">${scenes.map((s,i)=>storyScene(s,i,scenes.length,chars)).join('')}</div><p class="duration-total" id="story-total">Tổng thời lượng dự kiến: ${durationText(scenes.reduce((n,s)=>n+Number(s.duration||15),0))} (${scenes.length} phân cảnh liên hoàn)</p><div class="actions">${btn('▶ Tạo '+scenes.length+' phân cảnh phim','story-run','primary')}${btn('Lưu dự án, chạy sau','workflow-save','outline','data-module="storyboard"')}</div><p class="status-note">Prompt gốc được giữ nguyên. Khóa nối cảnh, giọng cố định và hậu kỳ tự động cần kiểm thử trên Muse; dữ liệu thiết lập được lưu riêng.</p></section></form></div></div>`}
function aff(){const d=workflowDraft('aff'),source=d.source||'link';return pagebar('Video Aff','Dán link sản phẩm Shopee (hoặc ảnh + thông tin) → kịch bản, người dẫn, từng cảnh và video bán hàng',btn('♧ Nút Lấy SP','product-helper')+btn('＋ Video mới','new-workflow','primary','data-module="aff"'))+`<div class="workspace">${side('aff','Video mới')}<div class="content"><form id="view-form" class="panel formpanel aff-form"><h2><span class="heading-icon">${icon('aff')}</span> Video bán hàng từ link Shopee</h2><small>Dán link sản phẩm (hoặc tải ảnh + nhập thông tin). Dùng ảnh thật và thông tin đã kiểm tra để lên kịch bản, tạo người dẫn và clip bán hàng.</small><label>Nguồn sản phẩm</label>${segment('source',[['link','↗ Link Shopee'],['manual','▧ Ảnh + thông tin']],source,'data-source-choice')}<div data-aff-source="link" ${source==='link'?'':'hidden'}><div class="product-link-row">${input('','product_link',d.product_link||'','text','placeholder="Dán link sản phẩm Shopee (vn.shp.ee/…)"')}${btn('↗ Mở trong Chrome','product-open')}</div><small>Mở trang sản phẩm trong trình duyệt đã đăng nhập Shopee. Chức năng tự lấy dữ liệu từ Shopee chưa được xác minh; hiện dùng tab Ảnh + thông tin để nhập dữ liệu đã kiểm tra.</small></div><div data-aff-source="manual" ${source==='manual'?'':'hidden'}><div class="grid three">${input('Tên sản phẩm','product_name',d.product_name||'','text','placeholder="vd: Nồi chiên không dầu 5L"')}${input('Giá <span class="muted">(tùy chọn)</span>','price',d.price||'','text','placeholder="vd: 1.290.000đ"')}${input('Link sản phẩm <span class="muted">(tùy chọn, ghi vào caption)</span>','manual_product_link',d.manual_product_link||'','url','placeholder="https://…"')}</div>${area('Thông tin / công dụng / cách dùng <span class="muted">(Muse chỉ nói đúng những gì có ở đây)</span>','product_info',d.product_info||'','placeholder="Dán mô tả sản phẩm: chất liệu, kích thước, công dụng, cách dùng, ưu đãi…"')}<label>Ảnh thật sản phẩm <span class="muted">(1–8 ảnh, ảnh đầu = ảnh chính; giúp Muse vẽ đúng sản phẩm)</span></label><div class="product-gallery" data-product-refs data-drop-kind="product">${(d.product_refs||[]).map((id,i)=>`<div class="product-photo" data-ref-id="${id}"><img src="/refs/${id}" alt="Ảnh sản phẩm ${i+1}"><small>${i===0?'Ảnh chính':i+1}</small>${btn('×','product-image-remove','',`data-id="${id}" aria-label="Bỏ ảnh sản phẩm"`)}</div>`).join('')}${(d.product_refs||[]).length<8?btn('⇧<small>Thêm ảnh</small>','product-images','photo-add'):''}</div></div><div class="subheading">${input('Phong cách nội dung','content_style',d.content_style||'','text','placeholder="Ví dụ: Review sản phẩm, giới thiệu, giải đáp…"')}</div><div class="grid two">${input('Nhân vật / phong cách','character',d.character||'','text','placeholder="Chọn người dẫn / mô tả nhân vật"')}<div class="field"><label>Độ dài video</label>${segment('duration',[['15','15 giây'],['30','30 giây'],['45','45 giây'],['60','60 giây']],d.duration||'30')}</div></div><div class="grid three">${select('Giới tính người dẫn / giọng','gender',['Tự chọn','Nam','Nữ'],d.gender||'Tự chọn')}${select('Độ tuổi','age',['Tự chọn','18–25','26–35','36–45','46–60','Trên 60'],d.age||'Tự chọn')}${select('Ngôn ngữ','language',languages,d.language||'vi')}</div><div class="grid two">${input('Phong cách hình ảnh','style',d.style||'','text','placeholder="Ví dụ: Chân thực, điện ảnh…"')}<div class="field"><label>Tỷ lệ khung hình</label>${segment('ratio',[['9:16','9:16 dọc'],['16:9','16:9 ngang']],d.ratio||'9:16')}</div></div><div class="grid two"><div class="field"><label>Nhạc nền</label>${segment('music',[['muse','✧ Muse tạo'],['file','↑ File của tôi'],['none','× Không nhạc']],d.music||'none')}<div data-music-file-panel ${d.music==='file'?'':'hidden'}>${input('Đường dẫn file nhạc','music_file',d.music_file||'')}</div></div>${input('Câu kêu gọi ở khung kết','cta',d.cta||'Xem link sản phẩm trong mô tả')}</div>${select('Nơi đặt đường dẫn mua hàng','publishing_context',[['description','Mô tả / caption'],['basket','Nền tảng có giỏ hàng']],d.publishing_context||'description')}${input('Link affiliate của bạn <span class="muted">(ghi vào file caption; trống = link sản phẩm)</span>','affiliate',d.affiliate||'','url','placeholder="https://s.shopee.vn/…"')}${input('Kiểu mở đầu (hook)','hook',d.hook||'','text','placeholder="Chọn / nhập kiểu mở đầu thu hút"')}${area('Ghi chú cho kịch bản <span class="muted">(tùy chọn: khách hàng mục tiêu, ưu đãi đang chạy, điều muốn nhấn mạnh…)</span>','notes',d.notes||'','placeholder="vd: nhắm sinh viên, nhấn mạnh nhỏ gọn bỏ túi; đang có freeship"')}<div class="checks">${check('Nhãn “Có sử dụng AI”','ai_label',d.ai_label!==false)}${check('Nhãn “Quảng cáo”','ad_label',d.ad_label!==false)}${check('Khung kết (ảnh thật + giá + nút mua)','end_card',d.end_card!==false)}${check('Hiện giá','show_price',d.show_price!==false)}${check('Phụ đề','subtitles',d.subtitles!==false)}</div><div class="notice">Chỉ dùng thông tin sản phẩm đã xác minh. Clip tạo ra cần duyệt lời thoại và thời lượng; nhạc Muse, khung kết tự động và tự kiểm tra thoại chưa hoàn thiện.</div><div class="actions">${btn('▶ Làm video tự động','workflow-auto','primary','data-module="aff"')}${btn('＋ Tạo dự án, chạy từng bước','workflow-save','outline','data-module="aff"')}${btn('☷ Thêm nhiều link vào hàng chờ…','workflow-bulk','','data-module="aff"')}</div><ol class="steps"><li><strong>Sản phẩm:</strong> dùng tên, mô tả, giá và ảnh thật đã kiểm tra.</li><li><strong>Kịch bản:</strong> mở đầu thu hút, lời thoại theo từng cảnh, tiêu đề, caption và hashtag.</li><li><strong>Người dẫn → ảnh cảnh:</strong> gắn ảnh sản phẩm vào đúng cảnh để giữ đúng bao bì.</li><li><strong>Clip:</strong> kiểm tra giọng nói, nội dung và thời lượng trước khi duyệt.</li><li><strong>Dựng video:</strong> duyệt clip trong Thư viện, ghép video hoặc nhập SRT để dựng bản cuối.</li></ol>${d.id?`<div class="notice">${badge(d.status)} ${esc(d.error||'Đã lưu dự án trên máy.')}</div>`:''}</form></div></div>`}

function accounts(){return `<div class="account-tools"><label>TK chạy đồng thời</label><input id="account-limit" type="number" min="1" value="${S.settings.account_limit}"><label>Tổng số luồng</label><input id="thread-limit" type="number" min="1" value="${S.settings.thread_limit}"><label>Chế độ</label><select id="distribution"><option value="round_robin" ${S.settings.distribution==='round_robin'?'selected':''}>Luân phiên</option><option value="sequential" ${S.settings.distribution==='sequential'?'selected':''}>Lần lượt</option></select><div class="right">${btn('Kiểm tra hạn mức','account-all','','data-value="quota"')}${btn('Kiểm tra cookie','account-all','','data-value="check"')}${btn('Làm mới cookie','account-all','','data-value="login"')}${btn('■ Dừng','queue-stop','danger')}${btn('＋ Thêm tài khoản','account-add','primary')}</div></div><div class="workspace"><section class="panel content" style="padding:0">${S.accounts.length?`<table><thead><tr><th>BẬT</th><th>TÀI KHOẢN</th><th>ẢNH / VIDEO</th><th>PROXY</th><th>COOKIE / TRẠNG THÁI</th><th>HẠN MỨC</th><th>THAO TÁC</th></tr></thead><tbody>${S.accounts.map(a=>`<tr><td><input type="checkbox" data-account-toggle="${a.id}" ${a.enabled!==false?'checked':''}></td><td class="account-name">${esc(a.name)}<small>${esc(a.email||'')}</small></td><td>${a.image_threads||5} / ${a.video_threads||5}</td><td>${esc(S.proxies.find(p=>p.id===a.proxy)?.server||'Không dùng')}</td><td>${badge(a.status)}${a.held?'<small> · Đang giữ</small>':''}</td><td>${esc(a.quota_text||'Chưa kiểm tra')}</td><td>${[['login','Login'],['check','Cookie'],['hold','Giữ'],['release','Thả'],['diagnose','Chẩn đoán']].map(([k,n])=>btn(n,'account-action','',`data-id="${a.id}" data-value="${k}"`)).join('')}${btn('Dán cookie','account-cookies','',`data-id="${a.id}"`)}${btn('✎','account-edit','',`data-id="${a.id}"`)}${btn('×','account-delete','danger',`data-id="${a.id}"`)}</td></tr>`).join('')}</tbody></table><div class="notice" style="margin:16px">Một profile chạy một tác vụ tại một thời điểm trong bản này để gắn đúng kết quả. Thông số nhiều luồng được lưu; mở rộng nhiều luồng cần xác minh cơ chế Muse.</div>`:empty('Chưa có tài khoản Muse','Bấm Thêm tài khoản, sau đó Login để đăng nhập. Mỗi tài khoản lưu phiên trong profile riêng.','♙')+`<div style="text-align:center;padding-bottom:45px">${btn('＋ Thêm tài khoản','account-add','primary')}</div>`}</section></div>`}
function proxy(){return pagebar('Proxy','Quản lý kết nối và gán proxy cho tài khoản',btn('Kiểm tra tất cả','proxy-check','outline')+btn('Tự gán','proxy-assign','outline')+btn('Gỡ gán tất cả','proxy-clear','outline')+btn('Xóa proxy lỗi','proxy-delete','danger')+btn('＋ Nhập proxy','proxy-add','primary'))+`<div class="workspace"><section class="panel content" style="padding:0">${S.proxies.length?`<table><thead><tr><th>ĐỊA CHỈ</th><th>TRẠNG THÁI</th><th>IP ĐẦU RA</th><th>ĐỘ TRỄ</th><th>TÀI KHOẢN DÙNG</th></tr></thead><tbody>${S.proxies.map(p=>`<tr><td>${esc(p.server)} ${p.username?'· '+esc(p.username):''}</td><td>${badge(p.status)}</td><td>${esc(p.ip||'—')}</td><td>${p.latency?`${p.latency} ms`:'—'}</td><td>${S.accounts.filter(a=>a.proxy===p.id).length}</td></tr>`).join('')}</tbody></table>`:empty('Chưa có proxy','Nhập host:port, host:port:user:pass, user:pass@host:port hoặc URL HTTP/SOCKS5.','◎')}</section></div>`}
function codex(){let plan=S.plans.find(p=>p.id===lastPlan)||S.plans.at(-1),d=drafts.codex||{};return pagebar('Codex AI','Tạo shot list, prompt và timeline để bạn kiểm tra trước khi dựng video',btn('↻ Kiểm tra kết nối','codex-check','outline'))+`<div class="settings"><div class="split"><div class="panel"><h3>Trạng thái Codex CLI</h3><p id="codex-status" class="muted">Bấm Kiểm tra kết nối để xác minh CLI và đăng nhập trên máy.</p>${btn('ⓘ Hướng dẫn CLI','codex-help','outline')}</div><form class="panel" id="view-form"><h3>Lập kế hoạch video</h3>${area('Brief / yêu cầu sản xuất','brief',d.brief||'','placeholder="Chủ đề, thời lượng, hình ảnh, giọng đọc, nhạc nền…"')}<div class="grid two"><div class="field"><label>Dự án tool</label><select name="project">${projectOptions(d.project||project)}</select></div>${select('Tỷ lệ khung hình','ratio',['16:9','9:16','1:1'],d.ratio||'16:9')}</div>${btn('▶ Lập kế hoạch','codex-plan','primary')}</form></div><div class="panel" style="margin-top:15px"><div class="inline"><h3>Tiến trình và log</h3><div class="right">${btn('Xóa log','logs-clear')}</div></div><div class="result">${S.logs.slice(0,15).reverse().map(l=>`<div class="logline ${l.level}">${new Date(l.created*1000).toLocaleTimeString('vi-VN')} · ${esc(l.text)}</div>`).join('')||'Chưa có phiên chạy'}</div></div><div class="panel" style="margin-top:15px"><div class="inline"><h3>Kết quả kế hoạch</h3><div class="right"><label style="margin:0"><input type="checkbox" id="plan-run">Chạy ngay</label>${btn('Đưa vào hàng đợi','plan-enqueue','outline',plan?`data-id="${plan.id}"`:'disabled')}${btn('Dùng prompt trong Studio','plan-studio','outline',plan?`data-id="${plan.id}"`:'disabled')}</div></div>${plan?`<pre class="result">${esc(JSON.stringify(plan.plan,null,2))}</pre>`:empty('Chưa có kế hoạch','Kết quả hiển thị shot list, prompt, timeline và ghi chú.','✧')}</div></div>`}
function settings(){let s=S.settings;return pagebar('Cài đặt','',btn('↻ Khôi phục mẫu prompt','restore-templates')+btn('✓ Lưu cài đặt','save-settings','primary'))+`<form class="settings" id="view-form"><div class="grid four"><div class="panel"><h3>▱ Đầu ra</h3><label>Thư mục lưu</label><div class="inline" style="margin-bottom:14px"><input name="output" value="${esc(s.output)}">${btn('Chọn','choose-folder','outline')}</div>${select('Định dạng ảnh','image_format',['PNG'],'PNG')}<div class="checks">${check('Tạo thư mục con theo dự án','subfolders',s.subfolders)}</div></div><div class="panel"><h3>⚙ Chạy tác vụ</h3><div class="grid two">${input('Chờ ảnh (giây)','image_timeout',s.image_timeout,'number')}${input('Chờ video (giây)','video_timeout',s.video_timeout,'number')}${input('Số lần thử lại khi lỗi','retries',s.retries,'number')}${input('Nhắc Muse tạo lại (lần)','reminders',s.reminders,'number')}${input('Nghỉ giữa 2 tác vụ / TK (giây)','pause',s.pause,'number')}${input('Ngừng TK khi hạn mức ≥ (%)','quota_limit',s.quota_limit,'number')}</div>${select('Video có ảnh tham chiếu','reference_mode',[['direct','Gửi thẳng mọi ảnh cho Muse'],['multiple','Từ 2 ảnh: ghép khung đầu trước'],['always','Luôn ghép khung đầu trước']],s.reference_mode)}<div class="checks">${check('Tự bấm Approve / Cho phép','approve',s.approve)}</div></div><div class="panel"><h3>◎ Trình duyệt</h3>${select('Trình duyệt','browser',[['chrome','Google Chrome'],['msedge','Microsoft Edge']],s.browser)}${select('Cửa sổ khi chạy','window',[['visible','Hiển thị'],['offscreen','Ẩn ngoài màn hình']],s.window)}${input('Tự đóng khi rảnh (phút, 0 = không)','idle_minutes',s.idle_minutes,'number')}<div class="status-note">Profile riêng cho từng tài khoản.</div></div><div class="panel"><h3>♩ Lồng tiếng VoiceTube</h3><small>API key dùng chung với mục Làm phim.</small>${voiceKeyEditor('settings-voicetube-key')}</div></div><div class="panel templates"><h3>✧ Mẫu prompt gửi Muse</h3><small>Biến: {prompt} nội dung nguyên văn · {ratio} tỷ lệ · {count} số ảnh</small><div class="checks">${check('Gửi prompt nguyên văn (không thêm mẫu lệnh)','raw_prompt',s.raw_prompt)}</div><div class="grid two">${Object.entries({image:'Ảnh',image_ref:'Ảnh (có ảnh tham chiếu)',video:'Video',video_ref:'Video (từ ảnh)',opening:'Video nhiều ảnh – Bước 1: ghép khung đầu',animate:'Video nhiều ảnh – Bước 2: làm động khung đầu'}).map(([k,n])=>area(n,'template_'+k,s.templates[k])).join('')}</div></div><div class="panel advanced"><h3>‹› Nâng cao</h3><div class="grid two">${input('Địa chỉ Muse','muse_url',s.muse_url)}${area('Ghi đè selector (JSON) – khi Muse thay đổi giao diện','selectors',JSON.stringify(s.selectors,null,2),'placeholder="{\"prompt\":\"textarea\",\"send\":\"button...\"}"')}${input('Đường dẫn Codex CLI','codex',s.codex)}${select('Giao diện toàn app','theme',[['dark','Tối · Navy / Cyan sáng'],['light','Sáng · Trắng / Cyan']],s.theme||'dark')}${input('Máy chủ cập nhật (tùy chọn)','update_url',s.update_url||'')}</div><div class="actions">${btn('Kiểm tra cập nhật','check-updates','outline')}${btn('Xem khả năng bản hiện tại','capabilities','outline')}</div><div class="status-note">Cập nhật theo lựa chọn của bạn. Các chức năng tích hợp chỉ được công nhận sau khi kiểm tra thực tế.</div></div></form>`}
function connectionGuide(){return pagebar('Hướng dẫn kết nối','Thực hiện lần đầu theo các bước bên dưới.')+`<div class="connection-guide"><div class="guide-grid">
<section class="panel guide-card"><div class="guide-heading"><span class="guide-number">1</span><h2>Kết nối Muse</h2></div>
<ol class="guide-list"><li>Vào <strong>Cài đặt</strong>, chọn Chrome / Edge và kiểm tra <strong>Địa chỉ Muse</strong> trong mục Nâng cao. Bấm <strong>Lưu cài đặt</strong>.</li><li>Vào <strong>Tài khoản → Thêm tài khoản</strong>, đặt tên rồi lưu.</li><li>Bấm <strong>Login</strong> và đăng nhập Muse trên cửa sổ trình duyệt vừa mở.</li><li>Quay lại tool, bấm <strong>Cookie</strong>. Khi hiện <strong>Sẵn sàng</strong>, bấm <strong>Thả</strong>.</li></ol>
<p class="guide-note">Nếu chưa kết nối được, bấm Chẩn đoán để kiểm tra. Trước khi chạy hàng loạt, cần xác minh bộ nhận kết quả Muse và thử 1 tác vụ.</p>
<div class="actions">${btn('Mở Tài khoản','tab','outline','data-tab="accounts"')}${btn('Mở Cài đặt','tab','','data-tab="settings"')}</div></section>
<section class="panel guide-card"><div class="guide-heading"><span class="guide-number">2</span><h2>Kết nối Codex</h2></div>
<ol class="guide-list"><li>Cài <strong>Codex CLI</strong> trên máy theo tài liệu OpenAI.</li><li>Mở Terminal, gõ <code>codex login</code> rồi làm theo hướng dẫn đăng nhập.</li><li>Trong tool, vào <strong>Codex AI → Kiểm tra kết nối</strong>. Thấy <strong>Đã đăng nhập</strong> là xong.</li></ol>
<p class="guide-note">Không tìm thấy CLI? Vào Cài đặt → Nâng cao, chọn đúng Đường dẫn Codex CLI rồi lưu.</p>
<div class="actions">${btn('Mở Codex AI','tab','outline','data-tab="codex"')}</div></section>
<section class="panel guide-card"><div class="guide-heading"><span class="guide-number">3</span><h2>Kích hoạt key</h2></div>
<ol class="guide-list"><li>Nhận <strong>key admin cấp</strong> theo gói 1 tuần, 1 tháng, 3 tháng hoặc 6 tháng.</li><li>Bấm <strong>Kích hoạt key</strong> ở góc trên tool, rồi dán vào ô <strong>Mã kích hoạt</strong>.</li><li>Bấm <strong>Kích hoạt</strong>. Kích hoạt xong, kiểm tra <strong>số ngày còn lại và ngày hết hạn</strong>.</li></ol>
<p class="guide-note guide-license-note">Key gắn với mã máy, tự tính hạn từ lần kích hoạt đầu tiên. Cần đổi máy hoặc gia hạn? Gửi mã máy cho admin.</p>
<div class="actions">${btn('Mở kích hoạt key','license','outline')}</div></section>
</div><p class="guide-tip">Key VANTRONG08 dùng cho bản quyền tool. Đăng nhập Muse và Codex được thực hiện riêng.</p></div>`}

function licenseDetails(l){const date=t=>t?new Date(t*1000).toLocaleString('vi-VN'):'—';return `<div class="license-details" aria-live="polite"><div class="license-main-status"><strong>${esc(l.active?'Đã kích hoạt':({expired:'Đã hết hạn',revoked:'Đã thu hồi',inactive:'Chưa kích hoạt'})[l.status]||'Cần kiểm tra')}</strong><span>${l.active?`Còn <b>${l.days_remaining}</b> ngày`:''}</span></div><dl><div><dt>Gói sử dụng</dt><dd>${esc(l.plan_label||'Chưa có')}</dd></div><div><dt>Ngày kích hoạt</dt><dd>${date(l.activated_at)}</dd></div><div><dt>Ngày hết hạn</dt><dd>${date(l.expires_at)}</dd></div></dl><small>${esc(l.message||'')}</small></div>`}
function activationDialog(){let l=S.license||{};modal('Bản quyền VANTRONG08',`<p class="muted">Nhập key admin cấp. Key được gắn với mã máy bên dưới.</p><div class="field"><label>Mã máy</label><div class="inline"><input id="license-hwid" value="${esc(l.hwid||S.hwid)}" readonly aria-label="Mã máy">${btn('Sao chép','license-copy','outline')}</div></div>${input('Mã kích hoạt','key','','text','placeholder="Dán key admin cấp tại đây" autocomplete="off"')}<div id="license-info">${licenseDetails(l)}</div><div class="license-plans"><span>1 tuần</span><span>1 tháng</span><span>3 tháng</span><span>6 tháng</span></div><small>Gói và thời hạn do admin cấp. Bắt đầu tính từ lần kích hoạt đầu tiên.</small><div class="actions">${btn('Kích hoạt','license-submit','primary')}${btn('Kiểm tra / Gia hạn','license-check','outline')}${btn('Hướng dẫn','tab','','data-tab="guide"')}${btn('Đóng','close-modal','outline')}</div>`)}
function modal(title,body){$('#modal-body').innerHTML=btn('×','close-modal','close')+`<h2>${title}</h2>`+body;$('#modal').showModal()}
function formData(){const form=$('#view-form');if(!form)return {};const data=Object.fromEntries(new FormData(form));form.querySelectorAll('input[type=checkbox][name]').forEach(e=>data[e.name]=e.checked);return data}
function workflowData(module){const base=module==='storyboard'?storyModel():workflowDraft(module),data={...base,...formData(),module,id:workflow||undefined,project};data.name=data.name||({film:'Phim mới',aff:data.product_name||'Video Aff',storyboard:'Storyboard'}[module]);if(module==='storyboard'){data.characters=collectCharacters();data.scenes=collectScenes(base);data.original_refs=[...document.querySelectorAll('[data-original-refs] [data-ref-id]')].map(el=>el.dataset.refId);data.concurrency_limit=Number(data.concurrency_limit)}if(module==='aff')data.product_refs=[...document.querySelectorAll('[data-product-refs] [data-ref-id]')].map(el=>el.dataset.refId);return data}
async function saveWorkflow(module){let w=await api('/api/workflow/save',workflowData(module));workflow=w.id;drafts[module]=structuredClone(w);await refresh();return w}
async function watch(value,onDone){if(!value?.job){if(value?.message)toast(value.message);if(onDone)await onDone(value);return value}pending.add(value.job);toast('Đang xử lý…');for(;;){await new Promise(r=>setTimeout(r,1500));let j=await api('/api/job/'+value.job);if(j.status==='error'){pending.delete(value.job);throw Error(j.error)}if(j.status==='done'){pending.delete(value.job);if(j.result?.message)toast(j.result.message);await refresh();if(onDone)await onDone(j.result);return j.result}}}
function pick(accept,multiple,fn){let f=$('#file-input');f.webkitdirectory=false;f.value='';f.accept=accept;f.multiple=multiple;f.onchange=()=>Promise.resolve(fn([...f.files])).catch(e=>toast(e.message,true));f.click()}
async function uploads(files,mode='ref'){for(let f of files){if(f.size>200*1024*1024)throw Error('File tối đa 200 MB.');let r=await fetch('/api/upload?kind='+mode+'&project='+encodeURIComponent(project)+'&name='+encodeURIComponent(f.name),{method:'POST',body:f});let v=await r.json();if(!r.ok)throw Error(v.error);if(mode==='ref')refIds.add(v.id)}await refresh();toast('Đã nhập file thật vào ứng dụng.')}
async function uploadWorkflowImages(files,target,index){
  if(!files.length)return;if(workflowUpload)throw Error('Đang tải ảnh. Đợi hoàn tất trước khi chọn thêm.');const module=target==='product'?'aff':'storyboard',d=workflowData(module);
  const capacity=target==='original'?4-(d.original_refs||[]).length:target==='product'?8-(d.product_refs||[]).length:target==='scene'?1:d.scenes.length;
  if(files.length>capacity)throw Error(target==='original'?'Chỉ dùng tối đa 4 ảnh gốc.':target==='product'?'Chỉ dùng tối đa 8 ảnh sản phẩm.':'Số ảnh vượt số cảnh có thể gắn.');
  for(const f of files)if(!/\.(png|jpe?g|webp)$/i.test(f.name)||f.size>20*1024*1024)throw Error('Dùng ảnh PNG/JPG/WebP, tối đa 20 MB/ảnh.');
  let added=0;workflowUpload=true;try{for(const f of files){const r=await fetch('/api/upload?kind=ref&project='+encodeURIComponent(project)+'&name='+encodeURIComponent(f.name),{method:'POST',body:f}),v=await r.json();if(!r.ok)throw Error(v.error||'Không tải được ảnh.');if(target==='original')d.original_refs.push(v.id);else if(target==='product')(d.product_refs??=[]).push(v.id);else {const slot=target==='scene'?index:added;d.scenes[slot].refs=[v.id];d.scenes[slot].storyboard_name=f.name;}added++;}}finally{const latest=workflowData(module);if(target==='original')latest.original_refs=d.original_refs;else if(target==='product')latest.product_refs=d.product_refs;else for(let n=0;n<added;n++){const slot=target==='scene'?index:n;latest.scenes[slot].refs=d.scenes[slot].refs;latest.scenes[slot].storyboard_name=d.scenes[slot].storyboard_name}drafts[module]=latest;workflowUpload=false;await refresh(false);if(tab===module)draw()}
  toast('Đã gắn '+added+' ảnh vào đúng '+(target==='product'?'sản phẩm':target==='original'?'nhóm ảnh gốc':'phân cảnh')+'. Bấm Lưu dự án để lưu thiết lập.');
}
async function applySceneCount(n){if(!Number.isInteger(n)||n<4||n>30)throw Error('Số phân cảnh từ 4 đến 30.');const d=workflowData('storyboard');if(n<d.scenes.length&&!confirm('Giảm số cảnh sẽ bỏ dữ liệu các cảnh cuối. Tiếp tục?'))return;d.scenes=Array.from({length:n},(_,i)=>d.scenes[i]||newScene(d.characters[0]?.id));const saved=await api('/api/workflow/save',d);workflow=saved.id;drafts.storyboard=saved;await refresh()}
async function importStoryPrompts(raw){const parts=await api('/api/prompts/split',{raw,delimiter:'promt08'}),d=workflowData('storyboard');if(parts.length!==d.scenes.length)throw Error('Số prompt ('+parts.length+') phải bằng số cảnh ('+d.scenes.length+').');parts.forEach((p,i)=>d.scenes[i].prompt=p.text);drafts.storyboard=d;if($('#modal').open)$('#modal').close();draw();toast('Đã gắn prompt nguyên văn theo thứ tự. Bấm Lưu dự án để lưu.');}
function accountModal(a={}){modal(a.id?'Sửa tài khoản Muse':'Thêm tài khoản Muse',`<form id="account-form" autocomplete="off">${!a.id?segment('account_mode',[['single','Một tài khoản'],['bulk','Nhiều tài khoản']],'single'):''}<div data-account-mode="single"><div class="grid two">${input('Tên hiển thị','name',a.name||'','text','placeholder="Tài khoản 1" maxlength="120"')}${input('Email <span class="muted">(tùy chọn)</span>','email',a.email||'','email','placeholder="email@outlook.com"')}${input('Mật khẩu <span class="muted">(tùy chọn — để tự điền khi Login)</span>','password','','password',`autocomplete="new-password" placeholder="${a.has_password?'Đã lưu · để trống để giữ nguyên':''}"`)}${select('Proxy','proxy',[['','— Không dùng proxy —'],...S.proxies.map(p=>[p.id,p.server])],a.proxy||'')}${input('Luồng ảnh','image_threads',a.image_threads||5,'number','min="1" max="100"')}${input('Luồng video','video_threads',a.video_threads||5,'number','min="1" max="100"')}</div>${a.has_password?`<div class="checks">${check('Xóa mật khẩu đã lưu','clear_password',false)}</div>`:''}${input('Dùng profile Chrome đã đăng nhập sẵn <span class="muted">(tùy chọn, thư mục profile riêng)</span>','profile',a.profile||'','text','placeholder="Để trống = tool tự tạo profile riêng"')}</div><div data-account-mode="bulk" hidden><label>Mỗi dòng 1 tài khoản: <code>email|mật khẩu|proxy</code> <span class="muted">(mật khẩu, proxy không bắt buộc)</span></label><textarea id="account-bulk-raw" spellcheck="false" autocomplete="off" placeholder="abc@outlook.com|matkhau|1.2.3.4:8080:user:pass&#10;xyz@outlook.com&#10;Tài khoản phụ"></textarea></div><small>Sau khi thêm, bấm <b>Login</b> ở từng tài khoản để mở cửa sổ đăng nhập, hoặc bấm <b>Dán cookie</b> để nhập cookie có sẵn. Mật khẩu được mã hóa trên Windows.</small><div class="modal-actions">${btn('Hủy','close-modal')}${btn(a.id?'Lưu thay đổi':'＋ Thêm','account-submit','primary',`data-id="${a.id||''}"`)}</div></form>`)}
async function newUIAction(a,b){const id=b.dataset.id,index=Number(b.dataset.index);switch(a){
case 'scene-quick':await applySceneCount(Number(b.dataset.value));return true;
case 'story-originals':pick('image/png,image/jpeg,image/webp',true,files=>uploadWorkflowImages(files,'original'));return true;
case 'story-batch':pick('image/png,image/jpeg,image/webp',true,files=>uploadWorkflowImages(files.sort((a,b)=>a.name.localeCompare(b.name,undefined,{numeric:true})),'batch'));return true;
case 'story-image':pick('image/png,image/jpeg,image/webp',false,files=>uploadWorkflowImages(files,'scene',index));return true;
case 'product-images':pick('image/png,image/jpeg,image/webp',true,files=>uploadWorkflowImages(files,'product'));return true;
case 'story-remove-image':{const d=workflowData('storyboard');d.scenes[index].refs=[];drafts.storyboard=d;draw();return true;}
case 'story-original-remove':{const d=workflowData('storyboard');d.original_refs=d.original_refs.filter(x=>x!==id);d.characters.forEach(c=>{if(c.ref===id)c.ref=''});drafts.storyboard=d;draw();return true;}
case 'product-image-remove':{const d=workflowData('aff');d.product_refs=d.product_refs.filter(x=>x!==id);drafts.aff=d;draw();return true;}
case 'story-character-add':{const d=workflowData('storyboard');if(d.characters.length>=30)throw Error('Tối đa 30 nhân vật.');let n=1;while(d.characters.some(c=>c.id===newCharacter(n).id))n++;d.characters.push(newCharacter(n));drafts.storyboard=d;draw();return true;}
case 'story-character-remove':{const d=workflowData('storyboard');d.characters=d.characters.filter(c=>c.id!==id);d.scenes.forEach(s=>s.characters=(Array.isArray(s.characters)?s.characters:[]).filter(c=>c!==id));drafts.storyboard=d;draw();return true;}
case 'story-match':{const d=workflowData('storyboard');d.scenes.forEach((s,i)=>{if(i)s.opening=d.scenes[i-1].ending||`Theo khung kết thúc Cảnh ${String(i).padStart(2,'0')}`});drafts.storyboard=d;draw();toast('Đã gắn thông tin nối cảnh. Chưa tạo hay xác minh khung hình kết thúc trên Muse.');return true;}
case 'story-import':pick('.txt',false,async files=>importStoryPrompts(new TextDecoder('utf-8',{fatal:true,ignoreBOM:true}).decode(await files[0].arrayBuffer())));return true;
case 'account-cookies':modal('Dán cookie tài khoản',`<small>Nhập mảng JSON cookie của website Muse đang dùng. Cookie chỉ nhập vào profile của tài khoản này.</small><textarea id="account-cookie-json" spellcheck="false" autocomplete="off" placeholder='[{"name":"…","value":"…","domain":"…","path":"/"}]'></textarea><div class="modal-actions">${btn('Hủy','close-modal')}${btn('Nhập và kiểm tra','account-cookie-save','primary',`data-id="${id}"`)}</div>`);return true;
case 'account-cookie-save':{let cookies;try{cookies=JSON.parse($('#account-cookie-json').value)}catch{throw Error('Cookie phải là JSON hợp lệ.')}if(!Array.isArray(cookies))throw Error('Cookie phải là một mảng JSON.');await watch(await api('/api/accounts/action',{id,action:'cookies',cookies}));$('#account-cookie-json').value='';$('#modal').close();return true;}
default:return false;
}}

document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;e.preventDefault();let a=b.dataset.action,id=b.dataset.id,v=b.dataset.value;try{if(workflowUpload&&['tab','new-workflow','open-workflow','workflow-save','workflow-auto','scene-apply','scene-quick','story-run','story-character-remove'].includes(a))throw Error('Đang tải ảnh. Đợi hoàn tất trước khi chuyển hoặc lưu dự án.');remember();if(await newUIAction(a,b))return;switch(a){case 'tab':if($('#modal').open)$('#modal').close();tab=b.dataset.tab;workflow=null;selected.clear();draw();break;case 'theme':{const theme=b.dataset.themeValue|| (document.body.classList.contains('light')?'dark':'light');applyTheme(theme);await api('/api/settings',{theme});S.settings.theme=theme;break;}case 'close-modal':$('#modal').close();break;case 'refresh':await refresh();break;case 'kind':kind=v;draw();break;case 'mapping':mapping=v;draw();break;case 'task-filter':filter=v;draw();break;case 'library-filter':libraryKind=v;draw();break;case 'project-add':{let name=prompt('Tên dự án mới');if(name){let p=await api('/api/projects/save',{name});project=p.id;await refresh()}break}case 'project-rename':{let p=S.projects.find(p=>p.id===project),name=prompt('Đổi tên dự án',p.name);if(name){await api('/api/projects/save',{id:project,name});await refresh()}break}case 'project-delete':if(confirm('Xóa dự án và tác vụ khỏi ứng dụng? File đã xuất vẫn được giữ.')){await api('/api/projects/delete',{id:project});project='default';await refresh()}break;case 'clear-prompts':drafts.studio={raw:'',delimiter:$('#delimiter').value};rawFile=null;draw();break;case 'import-prompts':pick('.txt',false,async files=>{rawFile=new TextDecoder('utf-8',{fatal:true,ignoreBOM:true}).decode(await files[0].arrayBuffer());drafts.studio={raw:rawFile,delimiter:$('#delimiter').value};draw();toast('Đã nhập TXT nguyên văn.')});break;case 'upload-folder':{let f=$('#file-input');f.value='';f.webkitdirectory=true;f.multiple=true;f.onchange=()=>uploads([...f.files].filter(x=>/\.(png|jpe?g|webp)$/i.test(x.name)).sort((a,b)=>a.name.localeCompare(b.name,undefined,{numeric:true}))).then(()=>{mapping='pair';draw()}).catch(e=>toast(e.message,true));f.click();break}case 'upload-refs':pick('image/png,image/jpeg,image/webp',true,f=>uploads(f));break;case 'import-media':pick('image/*,video/*',true,f=>uploads(f,'media'));break;case 'create-run':case 'create-only':{let r=await api('/api/tasks/bulk',{raw:rawFile??$('#prompts').value,delimiter:$('#delimiter').value,project,kind,ratio:$('[name="task-ratio"]').value,count:Number($('[name="task-count"]').value),refs:[...refIds],mapping,run:a==='create-run'});await refresh();toast(`Đã lưu ${r.length} tác vụ${a==='create-run'?' và bật hàng đợi':''}.`);break}case 'queue-start':await watch(await api('/api/queue/start',{}));await refresh();break;case 'queue-stop':await watch(await api('/api/queue/stop',{}));await refresh();break;case 'retry':{let ids=selected.size?[...selected]:S.tasks.filter(t=>t.project===project&&['error','review'].includes(t.status)).map(t=>t.id);if(!ids.length)throw Error('Chưa có tác vụ lỗi để chạy lại.');if(!confirm('Bạn đã kiểm tra Muse và xác nhận có thể gửi lại các tác vụ này?'))break;await api('/api/tasks/action',{ids,action:'retry',reviewed:true});await refresh();break}case 'tasks-delete':if(selected.size&&confirm('Xóa các tác vụ đã chọn?')){await api('/api/tasks/action',{ids:[...selected],action:'delete'});selected.clear();await refresh()}break;case 'task-detail':{let t=S.tasks.find(t=>t.id===id);modal('Chi tiết tác vụ',`<p>${badge(t.status)} · ${t.id}</p><pre class="result">${esc(t.prompt)}</pre><p class="status-note">${esc(t.error)}</p><small>Ảnh tham chiếu: ${t.refs.length} · Lần chạy: ${t.attempts}</small>`);break}case 'open-output':await watch(await api('/api/open',{}));break;case 'open-media':case 'media-folder':await api('/api/open',{media:id,folder:a==='media-folder'});break;case 'preview':{let m=S.media.find(m=>m.id===id);modal(esc(m.name),m.kind==='video'?`<video src="/media/${id}" controls autoplay></video>`:`<img src="/media/${id}" alt="${esc(m.name)}">`);break}case 'merge-tasks':{let ids=S.tasks.filter(t=>selected.has(t.id)).flatMap(t=>t.outputs).filter(id=>S.media.find(m=>m.id===id)?.kind==='video');if(!ids.length)throw Error('Chọn tác vụ có video hoàn thành để ghép.');await watch(await api('/api/merge',{ids,name:'Phim ghép'}));toast('Đã ghép và kiểm tra video.');break}case 'account-add':accountModal();break;case 'account-edit':accountModal(S.accounts.find(a=>a.id===id));break;case 'account-submit':{b.disabled=true;try{const form=$('#account-form'),mode=form.querySelector('[name=account_mode]:checked')?.value;if(mode==='bulk'){await api('/api/accounts/import',{raw:$('#account-bulk-raw').value,provider:form.querySelector('[name=provider]')?.value||'muse'});$('#account-bulk-raw').value=''}else{const d=Object.fromEntries(new FormData(form));delete d.account_mode;d.id=id||undefined;d.clear_password=!!form.querySelector('[name=clear_password]:checked');await api('/api/accounts/save',d);form.querySelector('[name=password]').value=''}$('#modal').close();await refresh();toast('Đã lưu tài khoản. Bấm Login hoặc Dán cookie để kết nối.')}finally{b.disabled=false}break;}
case 'account-delete':if(confirm('Xóa tài khoản khỏi danh sách? Profile đăng nhập trên máy được giữ.')){await api('/api/accounts/delete',{id});await refresh()}break;case 'account-action':await watch(await api('/api/accounts/action',{id,action:v}),r=>{if(v==='diagnose')modal('Chẩn đoán Muse',`<pre class="result">${esc(JSON.stringify(r,null,2))}</pre>`)});break;case 'account-all':for(let ac of S.accounts)await watch(await api('/api/accounts/action',{id:ac.id,action:v}));break;case 'show-browser':{let a=S.accounts.find(a=>a.status==='ready')||S.accounts[0];if(!a)throw Error('Thêm tài khoản trước.');await watch(await api('/api/accounts/action',{id:a.id,action:'show'}));break}case 'browser-mode':await api('/api/settings',{window:S.settings.window==='offscreen'?'visible':'offscreen'});await refresh();break;case 'proxy-add':modal('Nhập proxy',area('Mỗi dòng một proxy','proxy-raw','', 'id="proxy-raw" placeholder="host:port:user:pass"')+btn('＋ Thêm','proxy-submit','primary'));break;case 'proxy-submit':await api('/api/proxies/add',{raw:$('#proxy-raw').value});$('#modal').close();await refresh();break;case 'proxy-check':await watch(await api('/api/proxies/check',{ids:S.proxies.map(p=>p.id)}));break;case 'proxy-assign':case 'proxy-clear':await api('/api/proxies/assign',{clear:a==='proxy-clear'});await refresh();break;case 'proxy-delete':if(confirm('Xóa các proxy báo lỗi?')){await api('/api/proxies/delete',{ids:S.proxies.filter(p=>p.status==='error').map(p=>p.id)});await refresh()}break;case 'new-workflow':workflow=null;drafts[b.dataset.module]={};draw();break;case 'open-workflow':workflow=id;tab=S.workflows.find(w=>w.id===id).module;delete drafts[tab];if($('#modal').open)$('#modal').close();draw();break;case 'workflow-queue':modal('Hàng chờ',S.workflows.filter(w=>w.module===b.dataset.module).map(w=>`<div class="scene">${esc(w.name)} ${badge(w.status)} ${btn('Mở dự án','open-workflow','outline',`data-id="${w.id}"`)}</div>`).join('')||'<p class="muted">Chưa có dự án.</p>');break;case 'workflow-save':await saveWorkflow(b.dataset.module);toast('Đã lưu dự án. Có thể mở lại để tiếp tục.');break;case 'workflow-auto':{let w=await saveWorkflow(b.dataset.module);await watch(await api('/api/workflow/start',{id:w.id}));break}case 'workflow-bulk':modal('Thêm nhiều dự án',area('Mỗi dòng một '+(b.dataset.module==='aff'?'link sản phẩm':'ý tưởng'),'bulk','', 'id="workflow-bulk"')+btn('Thêm vào hàng chờ','workflow-bulk-save','primary',`data-module="${b.dataset.module}"`));break;case 'workflow-bulk-save':{for(let line of $('#workflow-bulk').value.split('\n').filter(x=>x.trim()))await api('/api/workflow/save',{name:line.slice(0,65),module:b.dataset.module,idea:line,product_link:b.dataset.module==='aff'?line:'',status:'draft'});$('#modal').close();await refresh();break}case 'import-srt':pick('.srt',false,async f=>{let w=await api('/api/srt/import',{raw:new TextDecoder('utf-8',{fatal:true,ignoreBOM:true}).decode(await f[0].arrayBuffer()),name:f[0].name.replace(/\.srt$/i,'')});workflow=w.id;await refresh()});break;case 'render-srt':await watch(await api('/api/srt/render',{id}));toast('Đã dựng video và lưu SRT.');break;case 'scene-apply':await applySceneCount(Number($('#scene-count').value));break;case 'story-prompts':storyRaw=null;modal('Dán nhiều câu lệnh',area('Mỗi prompt bắt đầu bằng một dòng promt08','story-raw','', 'id="story-raw"')+btn('Gắn theo thứ tự cảnh','story-prompts-save','primary'));break;case 'story-prompts-save':await importStoryPrompts(storyRaw??$('#story-raw').value);break;case 'story-run':{let w=await saveWorkflow('storyboard');if(w.continuity)throw Error('Chế độ khóa mạch nối cần bộ điều khiển đầu/cuối cảnh đã xác minh. Tắt khóa mạch nối để chạy các cảnh độc lập.');await api('/api/storyboard/tasks',{id:w.id,run:true});tab='studio';await refresh();break}case 'characters':modal('Ảnh tham chiếu nhân vật / bối cảnh',`<small>Đặt mã CHAR_001 hoặc ENV_001. Mã được lưu riêng với prompt.</small>${S.refs.map(r=>`<div class="scene inline"><img src="/refs/${r.id}" style="width:60px;height:45px;object-fit:cover"><small>${esc(r.name)}</small><input data-ref-code="${r.id}" value="${esc(r.code)}"></div>`).join('')}${btn('Lưu mã','characters-save','primary')}`);break;case 'characters-save':for(let e of document.querySelectorAll('[data-ref-code]'))await api('/api/refs/save',{id:e.dataset.refCode,code:e.value});$('#modal').close();await refresh();break;case 'codex-check':await watch(await api('/api/codex/check',{}),r=>{if($('#codex-status'))$('#codex-status').textContent=r.message;toast(r.message,!r.ready)});break;case 'codex-help':modal('Kết nối Codex CLI','<p>Cài Codex CLI từ tài liệu chính thức OpenAI, chạy <code>codex login</code> trên Windows rồi bấm Kiểm tra kết nối.</p><p class="muted">Ứng dụng dùng Codex để lập kế hoạch trong chế độ chỉ đọc. Các tác vụ render được kiểm tra riêng trước khi chạy.</p>');break;case 'codex-plan':await watch(await api('/api/codex/plan',formData()),r=>{lastPlan=r.id});break;case 'plan-enqueue':await api('/api/plans/enqueue',{id,run:$('#plan-run').checked});toast('Đã thêm prompt của kế hoạch vào Studio.');await refresh();break;case 'plan-studio':{let p=S.plans.find(p=>p.id===id);drafts.studio={raw:p.plan.shots.map(s=>'promt08\n'+s.prompt).join('\n'),delimiter:'promt08'};rawFile=null;tab='studio';project=p.project;draw();break}case 'voice-key-save':{const field=$('#'+b.dataset.input);if(!field?.value.trim())throw Error('Dán API key VoiceTube vào ô trước khi lưu.');b.disabled=true;try{S.voicetube=await api('/api/voicetube/key',{key:field.value});field.value='';field.placeholder='Key đã lưu · nhập key mới để thay';document.querySelectorAll('[data-voicetube-status]').forEach(el=>el.textContent='Đã lưu key trên máy · Chưa xác minh tạo giọng VoiceTube.');toast(S.voicetube.message)}finally{b.disabled=false}break;}case 'save-settings':{let d=formData();d.selectors=JSON.parse(d.selectors);d.templates={};for(let k of Object.keys(S.settings.templates)){d.templates[k]=d['template_'+k];delete d['template_'+k]}for(let k of ['image_timeout','video_timeout','retries','reminders','pause','quota_limit','idle_minutes'])d[k]=Number(d[k]);await api('/api/settings',d);await refresh();toast('Đã lưu cài đặt.');break}case 'restore-templates':if(confirm('Khôi phục 6 mẫu prompt? Prompt trong dự án được giữ.')){await api('/api/restore-templates',{});await refresh()}break;case 'choose-folder':await watch(await api('/api/folder',{}),r=>{if(r.path)$('[name="output"]').value=r.path});break;case 'check-updates':await watch(await api('/api/updates',{}));break;case 'capabilities':modal('Khả năng bản hiện tại',`<p>Quản lý dự án, tác vụ, tham chiếu, SRT, ghép video và lưu dữ liệu hoạt động trên máy.</p><p>Bản quyền cần cấu hình máy chủ và khóa công khai của admin. Phần Muse cần đăng nhập, selector và lượt render kiểm thử. VoiceTube và nhiều luồng trên cùng profile chưa hoàn thiện.</p><p>Thông số chưa áp dụng không được công nhận là đã hoạt động.</p>`);break;case 'license':activationDialog();break;case 'license-submit':await watch(await api('/api/license',{key:$('[name="key"]').value}));$('#modal').close();activationDialog();break;case 'license-check':await watch(await api('/api/license/check',{}));$('#modal').close();activationDialog();break;case 'license-copy':try{await navigator.clipboard.writeText($('#license-hwid').value);toast('Đã sao chép mã máy.')}catch{$('#license-hwid').select();toast('Chọn mã máy rồi nhấn Ctrl+C.')}break;case 'logs':modal('Nhật ký',`<div class="result">${S.logs.map(l=>`<div class="logline ${l.level}">${new Date(l.created*1000).toLocaleString('vi-VN')} · ${esc(l.text)}</div>`).join('')||'Chưa có nhật ký.'}</div>`);break;case 'logs-clear':await api('/api/logs/clear',{});await refresh();break;case 'product-open':{let url=$('[name="product_link"]').value;if(!/^https:\/\/(?:[^/]+\.)?(?:shopee\.vn|shp\.ee)\//.test(url))throw Error('Nhập link Shopee hợp lệ.');window.open(url,'_blank','noopener');break}case 'product-helper':modal('Nút Lấy SP',`<p>Trên trang sản phẩm Shopee đã mở, dùng dấu trang để sao chép tên, mô tả, giá và ảnh từ dữ liệu công khai đang hiển thị.</p><p class="muted">Trong bản này, dùng nguồn Ảnh + thông tin để nhập dữ liệu sản phẩm đã kiểm tra. Chưa tự động lấy dữ liệu qua Shopee.</p>`);break;default:throw Error('Chức năng chưa hoàn thiện trong bản này.')}}catch(err){toast(err.message,true)}});
document.addEventListener('change',async e=>{let t=e.target;try{if(t.name==='source'){document.querySelectorAll('[data-aff-source]').forEach(el=>el.hidden=el.dataset.affSource!==t.value)}if(t.name==='account_mode'){document.querySelectorAll('[data-account-mode]').forEach(el=>el.hidden=el.dataset.accountMode!==t.value)}if(t.id==='scene-preset')$('#scene-count').value=t.value;if(t.name==='concurrency_limit'&&$('[data-requested-limit]'))$('[data-requested-limit]').textContent=t.value;if(t.matches('[data-scene-duration]')){const d=workflowData('storyboard');$('#story-total').textContent='Tổng thời lượng dự kiến: '+durationText(d.scenes.reduce((n,s)=>n+s.duration,0))+' ('+d.scenes.length+' phân cảnh liên hoàn)'}if(t.matches('[name=voice]')){const control=t.closest('.voice-control');control.querySelector('[data-voice-key-panel]').hidden=t.value!=='voicetube';control.querySelectorAll('.voice-choice').forEach(label=>label.classList.toggle('active',label.querySelector('input').checked))}if(t.matches('[name=music]')&&document.querySelector('[data-music-file-panel]'))document.querySelector('[data-music-file-panel]').hidden=t.value!=='file';if(t.id==='project'){remember();project=t.value;selected.clear();draw()}if(t.matches('[data-task]'))t.checked?selected.add(t.dataset.task):selected.delete(t.dataset.task);if(t.id==='select-all'){document.querySelectorAll('[data-task]').forEach(el=>{el.checked=t.checked;t.checked?selected.add(el.dataset.task):selected.delete(el.dataset.task)})}if(t.id==='quick-select'){selected=new Set(S.tasks.filter(x=>x.project===project&&(x.status===t.value||x.kind===t.value||(t.value==='error'&&x.status==='review'))).map(x=>x.id));draw()}if(t.matches('[data-ref]'))t.checked?refIds.add(t.dataset.ref):refIds.delete(t.dataset.ref);if(t.matches('[data-srt-media]')){let w=S.workflows.find(w=>w.id===workflow);w.scenes[Number(t.dataset.srtMedia)].media=t.value;await api('/api/workflow/save',w)}if(t.matches('[data-account-toggle]'))await api('/api/accounts/save',{id:t.dataset.accountToggle,enabled:t.checked});if(['account-limit','thread-limit','distribution'].includes(t.id))await api('/api/settings',{account_limit:Number($('#account-limit').value),thread_limit:Number($('#thread-limit').value),distribution:$('#distribution').value});if(t.id==='library-project')filterLibrary()}catch(err){toast(err.message,true)}});
function filterLibrary(){let q=$('#library-search').value.toLowerCase(),p=$('#library-project').value;document.querySelectorAll('[data-media-card]').forEach(el=>el.style.display=(!q||el.dataset.search.includes(q))&&(!p||el.dataset.project===p)?'':'none')}
document.addEventListener('input',e=>{if(e.target.id==='story-raw')storyRaw=null;if(e.target.id==='prompts')rawFile=null;if(e.target.id==='task-search'){let q=e.target.value.toLowerCase();document.querySelectorAll('[data-task-row]').forEach(el=>el.style.display=el.dataset.search.includes(q)?'':'none')}if(e.target.id==='library-search')filterLibrary()});
document.addEventListener('submit',e=>{e.preventDefault();if(e.target.id==='account-form')e.target.querySelector('[data-action=account-submit]')?.click()});
document.addEventListener('paste',e=>{if(e.target.id==='story-raw'){const raw=e.clipboardData.getData('text/plain');setTimeout(()=>storyRaw=raw,0)}});
document.addEventListener('dragover',e=>{if(e.target.closest('[data-drop-kind],.ref-drop'))e.preventDefault()});
document.addEventListener('drop',e=>{const target=e.target.closest('[data-drop-kind]');if(target){e.preventDefault();remember();uploadWorkflowImages([...e.dataTransfer.files],target.dataset.dropKind,Number(target.dataset.indexDrop)).catch(err=>toast(err.message,true));return}if(e.target.closest('.ref-drop')){e.preventDefault();remember();uploads([...e.dataTransfer.files]).catch(err=>toast(err.message,true))}});
let storyRaw=null,workflowUpload=false;
setInterval(async()=>{if(!S)return;const before=JSON.stringify([S.tasks,S.accounts,S.media,S.workflows]);try{await refresh(false);if(before!==JSON.stringify([S.tasks,S.accounts,S.media,S.workflows])&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)&&!$('#modal').open){remember();draw()}}catch{}},2500);refresh().catch(e=>toast(e.message,true));
